#include <bits/stdc++.h>
using namespace std;

#define rep(i, a, b) for(int i = (a); i < (b); i++)
#define all(v) (v).begin(), (v).end()

typedef long long ll;

const int MAXN = 600;

ll mod;
struct Mint {
    ll x;
    Mint() : x(0) {}
    Mint(ll _x) { x = _x % mod; if (x < 0) x += mod; }
    Mint operator+(const Mint &b) const { return Mint((x + b.x) % mod); }
    Mint operator-(const Mint &b) const { return Mint((x - b.x + mod) % mod); }
    Mint operator*(const Mint &b) const { return Mint((x * b.x) % mod); }
    Mint pow(ll e) const {
        Mint res(1), base(x);
        while (e > 0) {
            if (e & 1) res = res * base;
            base = base * base;
            e >>= 1;
        }
        return res;
    }
    Mint inv() const { return pow(mod - 2); }
};

Mint comb[MAXN][MAXN];
Mint a[MAXN], c[MAXN];
Mint dp[MAXN][MAXN][2], dpc[MAXN][MAXN][2];

ll sum_range(ll l, ll r) {
    if (l > r) return 0;
    return (l + r) * (r - l + 1) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m >> mod;

    for (int i = 0; i <= m; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j == 0 || j == i) comb[i][j] = 1;
            else comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    a[0] = 0; c[0] = 1;
    a[1] = 0; c[1] = 2;

    for (int i = 2; i <= m; ++i) {
        Mint tmp = 0, tmpc = 0;
        for (int l = 0; l <= i; ++l) {
            int r = i - 1 - l;
            tmp += c[l] * c[r] * Mint(sum_range(1, l) + sum_range(1, r)) * comb[i - 1][l]
                   + (a[l] * c[r] + a[r] * c[l]) * comb[i - 1][l] * (i + 1);
            tmpc += c[l] * c[r] * (i + 1) * comb[i - 1][l];
        }
        a[i] = tmp;
        c[i] = tmpc;
    }

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= m; ++j)
            for (int k = 0; k < 2; ++k)
                dpc[i][j][k] = 0;
    dpc[0][0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (j > i) continue;
            dpc[i][j][0] = dpc[i - 1][j][0] + dpc[i - 1][j][1];
            for (int k = 1; k <= j; ++k) {
                dpc[i][j][1] = dpc[i][j][1] + c[k] * comb[j][k] * dpc[i - k][j - k][0];
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (j > i) continue;
            dp[i][j][0] = dp[i - 1][j][0] + dp[i - 1][j][1];
            for (int k = 1; k <= j; ++k) {
                dp[i][j][1] = dp[i][j][1] + a[k] * comb[j][k] * dpc[i - k][j - k][0]
                                + dp[i - k][j - k][0] * c[k] * comb[j][k];
            }
        }
    }

    cout << (dp[n][m][0] + dp[n][m][1]).x << "\n";

    return 0;
}
